 4	#[derive(Debug,Clone,PartialEq,Eq)]
 5	pub struct WidgetSpec {
 6	    pub id:u32,pub parent_id:u32,pub axis:Axis,pub preferred_width:u32,pub preferred_height:u32,
 7	    pub padding:u32,pub gap:u32,pub color:u32,pub command_id:u32,pub state:u32,
 8	    pub widget_kind:u32,pub label:String,pub value:String,pub icon_kind:u32,
 9	}
10	impl WidgetSpec { pub fn new(id:u32,parent_id:u32)->Self { Self{id,parent_id,axis:Axis::Overlay,preferred_width:0,preferred_height:0,padding:0,gap:0,color:0,command_id:0,state:0,widget_kind:0,label:String::new(),value:String::new(),icon_kind:0} } }
11	fn add(tree:&mut Tree,s:&WidgetSpec,role:Role)->Result<(),TreeError>{
12	    let mut n=NodeSpec::new(s.id,s.parent_id);n.axis=s.axis;n.preferred_width=s.preferred_width;n.preferred_height=s.preferred_height;
13	    n.padding=s.padding;n.gap=s.gap;n.color=s.color;n.role=role;n.command_id=s.command_id;n.state=s.state;
14	    n.widget_kind=s.widget_kind;n.label.try_reserve_exact(s.label.len()).map_err(|_|TreeError::Allocation)?;n.label.push_str(&s.label);
15	    n.value.try_reserve_exact(s.value.len()).map_err(|_|TreeError::Allocation)?;n.value.push_str(&s.value);n.icon_kind=s.icon_kind;tree.add(n)
16	}
17	pub fn add_button(tree:&mut Tree,s:&WidgetSpec)->Result<(),TreeError>{add(tree,s,Role::Button)}
18	pub fn add_checkbox(tree:&mut Tree,s:&WidgetSpec)->Result<(),TreeError>{add(tree,s,Role::Checkbox)}
19	pub fn add_text_field(tree:&mut Tree,s:&WidgetSpec)->Result<(),TreeError>{add(tree,s,Role::TextField)}
20	pub fn add_slider(tree:&mut Tree,s:&WidgetSpec)->Result<(),TreeError>{add(tree,s,Role::Slider)}
21	pub fn add_row(tree:&mut Tree,s:&WidgetSpec)->Result<(),TreeError>{add(tree,s,Role::Row)}

