  7	fn linear_channel(color:u32,shift:u32)->f64{
  8	    let channel=((color>>shift)&255)as f64/255.0;
  9	    if channel<=0.04045{channel/12.92}else{((channel+0.055)/1.055).powf(2.4)}
 10	}
 11	fn contrast(first:u32,second:u32)->f64{
 12	    let luminance=|color|0.2126*linear_channel(color,24)+0.7152*linear_channel(color,16)+0.0722*linear_channel(color,8);
 13	    let (a,b)=(luminance(first),luminance(second));(a.max(b)+0.05)/(a.min(b)+0.05)
 14	}
