16	pub(crate) fn glyph(c: u8, row: usize) -> u8 {
17	    let c = if c.is_ascii_lowercase() { c.to_ascii_uppercase() } else { c };
18	    if c.is_ascii_digit() { return FONT[(c-b'0') as usize][row]; }
19	    if c.is_ascii_uppercase() { return FONT[10+(c-b'A') as usize][row]; }
20	    match c {
21	        b' '=>0,b'-'=>if row==3 {14}else{0},b'_'=>if row==6 {31}else{0},b'.'=>if row==6 {4}else{0},
22	        b','=>if row==6 {4}else if row==5 {8}else{0},b':'=>if row==2||row==5 {4}else{0},
23	        b';'=>if row==2||row==5 {4}else if row==6 {8}else{0},b'/'=>1 << if row>4 {0}else{4-row},
24	        b'\\'=>1 << if row<5 {row}else{4},b'#'=>if row==2||row==4 {31}else if row==1||row==5 {10}else{0},
25	        b'%'=>if row==0||row==6 {17}else if row==1||row==5 {2}else if row==2||row==4 {4}else{8},
26	        b'='=>if row==2||row==4 {14}else{0},b'+'=>if row==3 {14}else if matches!(row,1|2|4|5){4}else{0},
27	        b'['=>if row==0||row==6 {14}else{8},b']'=>if row==0||row==6 {14}else{2},
28	        b'<'=>if row==3 {2}else if row==2||row==4 {4}else if row==1||row==5 {8}else{0},
29	        b'>'=>if row==3 {8}else if row==2||row==4 {4}else if row==1||row==5 {2}else{0},
30	        b'('=>if row==0||row==6 {2}else if row==1||row==5 {4}else{8},
31	        b')'=>if row==0||row==6 {8}else if row==1||row==5 {4}else{2},
32	        b'!'=>if row<5||row==6 {4}else{0},b'?'=>if row==0 {14}else if row==1 {17}else if row==2 {2}else if row==3||row==6 {4}else{0},
33	        b'\''=>if row<2 {4}else{0},b'"'=>if row<2 {10}else{0},
34	        b'*'=>if row==1||row==5 {10}else if row==2||row==4 {4}else if row==3 {14}else{0},
35	        b'|'=>4,b'&'=>if row==0 {12}else if row==1||row==2 {18}else if row==3 {12}else if row==4||row==5 {21}else{10},
36	        _=>if row==0||row==6 {14}else if row==1||row==5 {17}else if row==2||row==4 {2}else{4},
37	    }
38	}
