40	pub(crate) fn valid_buffer(width:u32,height:u32,capacity:usize,stride:usize)->bool {
41	    let Some(row)=(width as usize).checked_mul(4) else{return false};
42	    width>0 && height>0 && stride>=row && (height as usize).checked_mul(stride).is_some_and(|n|capacity>=n)
43	}
44	
45	pub(crate) fn blend(dst:&mut [u8], color:u32, coverage:u8) {
46	    let alpha=((color&255)*coverage as u32+127)/255;
47	    let inv=255-alpha; let da=dst[3] as u32; let oa=alpha+(da*inv+127)/255;
48	    if oa==0{return}
49	    for (i,shift) in [24,16,8].into_iter().enumerate() {
50	        let src=(color>>shift)&255;
51	        let num=src*alpha*255+dst[i] as u32*da*inv;
52	        dst[i]=((num+oa*127)/(oa*255)) as u8;
53	    }
54	    dst[3]=oa as u8;
55	}
