57	/// Draw bounded legacy 5x7 scalar glyphs into caller-owned RGBA storage.
58	/// Non-ASCII UTF-8 scalars produce one `?`; continuation bytes are skipped.
59	pub fn scalar_text_draw(text:&str, clip:Rect, font_size_px:u32, color:u32,
60	    rgba:&mut [u8], width:u32, height:u32, stride:usize)->bool {
61	    if text.len()>1_048_576 || font_size_px==0 || clip.x>width || clip.y>height || clip.width>width-clip.x ||
62	        clip.height>height-clip.y || !valid_buffer(width,height,rgba.len(),stride) {return false}
63	    let scale=(font_size_px/13+u32::from(font_size_px%13!=0)).clamp(1,16);
64	    let glyph_h=7*scale; let y0=clip.y+(clip.height.saturating_sub(glyph_h))/2;
65	    let right=clip.x+clip.width; let bottom=clip.y+clip.height; let mut cursor=clip.x;
66	    for ch in text.chars().take(1_048_576) {
67	        let c=if ch.is_ascii() {ch as u8} else {b'?'};
68	        if cursor>right || right-cursor<5*scale {break}
69	        for row in 0..7 {for col in 0..5 {
70	            if glyph(c,row)&(1<<(4-col))==0 {continue}
71	            for sy in 0..scale {for sx in 0..scale {
72	                let x=cursor+col as u32*scale+sx; let y=y0+row as u32*scale+sy;
73	                if x>=clip.x&&x<right&&y>=clip.y&&y<bottom&&x<width&&y<height {
74	                    let at=y as usize*stride+x as usize*4; blend(&mut rgba[at..at+4],color,255);
75	                }
76	            }}
77	        }}
78	        cursor=match cursor.checked_add(6*scale){Some(v)=>v,None=>break};
79	    }
80	    true
81	}

