12	#[derive(Debug, Clone, Copy, PartialEq, Eq)] pub enum IconError { InvalidPath, TooComplex, InvalidBuffer, InvalidScale, InvalidIcon, Allocation }
13	#[derive(Debug, Clone, Copy)] struct Segment { x0:f64,y0:f64,x1:f64,y1:f64 }
14	const MAX_PATH:usize=2048; const MAX_SEGMENTS:usize=384; const MAX_SCALE:usize=3; const AXIS:usize=24;
15	
16	fn number(path:&str, at:&mut usize)->Result<f64,IconError>{
17	    let b=path.as_bytes(); while *at<b.len() && matches!(b[*at],b' '|b'\t'|b'\r'|b'\n'|b','){*at+=1}
18	    let start=*at; while *at<b.len() && matches!(b[*at],b'0'..=b'9'|b'+'|b'-'|b'.'|b'e'|b'E'){*at+=1}
19	    if start==*at || *at-start>=48{return Err(IconError::InvalidPath)}
20	    let n=path[start..*at].parse::<f64>().map_err(|_|IconError::InvalidPath)?;
21	    if !n.is_finite(){return Err(IconError::InvalidPath)} Ok(n)
22	}
23	fn add(out:&mut Vec<Segment>,s:Segment)->Result<(),IconError>{if out.len()>=MAX_SEGMENTS{return Err(IconError::TooComplex)} if ![s.x0,s.y0,s.x1,s.y1].iter().all(|v|v.is_finite()){return Err(IconError::InvalidPath)}out.push(s);Ok(())}
24	fn point(x:f64,y:f64)->bool{x.is_finite()&&y.is_finite()&&(0.0..=24.0).contains(&x)&&(0.0..=24.0).contains(&y)}
25	fn pair(path:&str,at:&mut usize,bounds:&mut IconBounds)->Result<(f64,f64),IconError>{let x=number(path,at)?;let y=number(path,at)?;if !point(x,y){return Err(IconError::InvalidPath)}bounds.left=bounds.left.min(x);bounds.right=bounds.right.max(x);bounds.top=bounds.top.min(y);bounds.bottom=bounds.bottom.max(y);Ok((x,y))}
26	fn cubic(out:&mut Vec<Segment>,p:(f64,f64),a:(f64,f64),b:(f64,f64),q:(f64,f64))->Result<(),IconError>{let(mut x0,mut y0)=p;for i in 1..=16{let t=i as f64/16.0;let u=1.0-t;let x=u*u*u*p.0+3.0*u*u*t*a.0+3.0*u*t*t*b.0+t*t*t*q.0;let y=u*u*u*p.1+3.0*u*u*t*a.1+3.0*u*t*t*b.1+t*t*t*q.1;add(out,Segment{x0,y0,x1:x,y1:y})?;x0=x;y0=y}Ok(())}
27	fn quadratic(out:&mut Vec<Segment>,p:(f64,f64),a:(f64,f64),q:(f64,f64))->Result<(),IconError>{let(mut x0,mut y0)=p;for i in 1..=12{let t=i as f64/12.0;let u=1.0-t;let x=u*u*p.0+2.0*u*t*a.0+t*t*q.0;let y=u*u*p.1+2.0*u*t*a.1+t*t*q.1;add(out,Segment{x0,y0,x1:x,y1:y})?;x0=x;y0=y}Ok(())}
28	fn arc(out:&mut Vec<Segment>,p:(f64,f64),mut rx:f64,mut ry:f64,rotation:f64,large:bool,sweep:bool,q:(f64,f64))->Result<(),IconError>{
29	    if p==q{return Ok(())} rx=rx.abs();ry=ry.abs();if rx==0.0||ry==0.0{return add(out,Segment{x0:p.0,y0:p.1,x1:q.0,y1:q.1})}
30	    let phi=rotation*PI/180.0;let(c,s)=(phi.cos(),phi.sin());let dx=(p.0-q.0)*0.5;let dy=(p.1-q.1)*0.5;let xp=c*dx+s*dy;let yp=-s*dx+c*dy;
31	    let lambda=xp*xp/(rx*rx)+yp*yp/(ry*ry);if lambda>1.0{let k=lambda.sqrt();rx*=k;ry*=k}let(rx2,ry2)=(rx*rx,ry*ry);let den=rx2*yp*yp+ry2*xp*xp;let num=rx2*ry2-den;let mut f=if den==0.0{0.0}else{(num/den).max(0.0).sqrt()};if large==sweep{f=-f}
32	    let cxp=f*rx*yp/ry;let cyp=f*-ry*xp/rx;let cx=c*cxp-s*cyp+(p.0+q.0)*0.5;let cy=s*cxp+c*cyp+(p.1+q.1)*0.5;
33	    let ux=(xp-cxp)/rx;let uy=(yp-cyp)/ry;let vx=(-xp-cxp)/rx;let vy=(-yp-cyp)/ry;let start=uy.atan2(ux);let mut delta=(ux*vy-uy*vx).atan2(ux*vx+uy*vy);if !sweep&&delta>0.0{delta-=2.0*PI}if sweep&&delta<0.0{delta+=2.0*PI}
34	    let steps=((delta.abs()*rx.max(ry)/0.65).ceil() as usize).clamp(4,64);let(mut x0,mut y0)=p;for i in 1..=steps{let angle=start+delta*i as f64/steps as f64;let mut x=cx+c*rx*angle.cos()-s*ry*angle.sin();let mut y=cy+s*rx*angle.cos()+c*ry*angle.sin();if i==steps{(x,y)=q}add(out,Segment{x0,y0,x1:x,y1:y})?;x0=x;y0=y}Ok(())
35	}
36	fn parse_path_data(path:&str)->Result<(Vec<Segment>,IconBounds),IconError>{
37	    if path.is_empty()||path.len()>MAX_PATH{return Err(IconError::InvalidPath)}let mut out=Vec::new();out.try_reserve(MAX_SEGMENTS).map_err(|_|IconError::Allocation)?;let mut bounds=IconBounds{left:24.0,top:24.0,right:0.0,bottom:0.0};let(mut at,mut cur,mut start,mut has)=(0,(0.0,0.0),(0.0,0.0),false);
38	    while at<path.len(){while at<path.len()&&matches!(path.as_bytes()[at],b' '|b'\t'|b'\r'|b'\n'|b','){at+=1}if at==path.len(){break}let cmd=path.as_bytes()[at] as char;at+=1;if cmd=='Z'{if !has{return Err(IconError::InvalidPath)}add(&mut out,Segment{x0:cur.0,y0:cur.1,x1:start.0,y1:start.1})?;cur=start;continue}if !matches!(cmd,'M'|'L'|'C'|'Q'|'A')||(cmd!='M'&&!has){return Err(IconError::InvalidPath)}
39	        match cmd {'M'=>{cur=pair(path,&mut at,&mut bounds)?;start=cur;has=true},'L'=>{let q=pair(path,&mut at,&mut bounds)?;add(&mut out,Segment{x0:cur.0,y0:cur.1,x1:q.0,y1:q.1})?;cur=q},'C'=>{let a=pair(path,&mut at,&mut bounds)?;let b=pair(path,&mut at,&mut bounds)?;let q=pair(path,&mut at,&mut bounds)?;cubic(&mut out,cur,a,b,q)?;cur=q},'Q'=>{let a=pair(path,&mut at,&mut bounds)?;let q=pair(path,&mut at,&mut bounds)?;quadratic(&mut out,cur,a,q)?;cur=q},'A'=>{let rx=number(path,&mut at)?;let ry=number(path,&mut at)?;let rot=number(path,&mut at)?;let la=number(path,&mut at)?;let sw=number(path,&mut at)?;let q=pair(path,&mut at,&mut bounds)?;if rx<0.0||rx>24.0||ry<0.0||ry>24.0||rot.abs()>360.0||!matches!(la,0.0|1.0)||!matches!(sw,0.0|1.0){return Err(IconError::InvalidPath)}arc(&mut out,cur,rx,ry,rot,la==1.0,sw==1.0,q)?;cur=q},_=>return Err(IconError::InvalidPath)}
40	    }
41	    if out.is_empty()||out.iter().any(|s|!point(s.x0,s.y0)||!point(s.x1,s.y1)){return Err(IconError::InvalidPath)}for s in &out{bounds.left=bounds.left.min(s.x0);bounds.left=bounds.left.min(s.x1);bounds.right=bounds.right.max(s.x0).max(s.x1);bounds.top=bounds.top.min(s.y0).min(s.y1);bounds.bottom=bounds.bottom.max(s.y0).max(s.y1)}Ok((out,bounds))
42	}
43	pub(crate) fn parse_path(path:&str)->Result<IconBounds,IconError>{parse_path_data(path).map(|(_,bounds)|bounds)}
44	
45	#[derive(Debug,Clone,PartialEq,Eq)] pub struct IconCache { masks:[Option<Vec<u8>>;216], legacy:[Option<Vec<u8>>;30] }
46	impl Default for IconCache { fn default()->Self { Self{masks:std::array::from_fn(|_|None),legacy:std::array::from_fn(|_|None)} } }
47	impl IconCache {
48	    pub fn new()->Self{Self::default()}
49	    pub fn clear(&mut self){self.masks.fill(None);self.legacy.fill(None)}
50	    fn mask(&mut self,icon:IconKind,scale:usize)->Result<&[u8],IconError>{
51	        if icon==IconKind::None||icon as usize>=IconKind::COUNT as usize||scale==0||scale>MAX_SCALE{return Err(IconError::InvalidIcon)}
52	        let index=icon as usize*4+scale;
53	        if self.masks[index].is_none(){
54	            let def=crate::icon_path_at(icon as usize-1).ok_or(IconError::InvalidIcon)?;let mut segs=Vec::new();segs.try_reserve(MAX_SEGMENTS).map_err(|_|IconError::Allocation)?;
55	            // Parsing is repeated to obtain segments; the same strict parser backs public validation.
