 48	static bool parse_number(const char *path, size_t length, size_t *offset,
 49	                         double *out_value)
 50	{
 51	    skip_separators(path, length, offset);
 52	    size_t start = *offset;
 53	    while (*offset < length) {
 54	        char c = path[*offset];
 55	        if ((c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.' ||
 56	            c == 'e' || c == 'E') (*offset)++;
 57	        else break;
 58	    }
 59	    size_t token_length = *offset - start;
 60	    if (token_length == 0U || token_length >= 48U) return false;
 61	    char token[48];
 62	    memcpy(token, path + start, token_length);
 63	    token[token_length] = '\0';
 64	    char *end = NULL;
 65	    errno = 0;
 66	    double value = strtod(token, &end);
 67	    if (errno == ERANGE || end != token + token_length || !isfinite(value)) return false;
 68	    *out_value = value;
 69	    return true;
 70	}
