140	static bool flatten_arc(ui_icon_segment *segments, size_t *count,
141	                        double x1, double y1, double rx, double ry,
142	                        double rotation, bool large_arc, bool sweep,
143	                        double x2, double y2)
144	{
145	    /* Convert SVG endpoint parameters using the SVG elliptical-arc algorithm. */
146	    if (x1 == x2 && y1 == y2) return true;
147	    rx = fabs(rx); ry = fabs(ry);
148	    if (rx == 0.0 || ry == 0.0) return add_segment(segments, count, x1, y1, x2, y2);
149	    double phi = rotation * UI_ICON_PI / 180.0;
150	    double cosine = cos(phi), sine = sin(phi);
151	    double dx = (x1 - x2) * 0.5, dy = (y1 - y2) * 0.5;
152	    double xp = cosine * dx + sine * dy;
153	    double yp = -sine * dx + cosine * dy;
154	    double lambda = xp * xp / (rx * rx) + yp * yp / (ry * ry);
155	    if (lambda > 1.0) { double scale = sqrt(lambda); rx *= scale; ry *= scale; }
156	    double rx2 = rx * rx, ry2 = ry * ry;
157	    double denominator = rx2 * yp * yp + ry2 * xp * xp;
158	    double numerator = rx2 * ry2 - denominator;
159	    double factor = denominator == 0.0 ? 0.0 : sqrt(fmax(0.0, numerator / denominator));
160	    if (large_arc == sweep) factor = -factor;
161	    double cxp = factor * rx * yp / ry;
162	    double cyp = factor * -ry * xp / rx;
163	    double cx = cosine * cxp - sine * cyp + (x1 + x2) * 0.5;
164	    double cy = sine * cxp + cosine * cyp + (y1 + y2) * 0.5;
165	    double ux = (xp - cxp) / rx, uy = (yp - cyp) / ry;
166	    double vx = (-xp - cxp) / rx, vy = (-yp - cyp) / ry;
167	    double start = atan2(uy, ux);
168	    double delta = atan2(ux * vy - uy * vx, ux * vx + uy * vy);
169	    if (!sweep && delta > 0.0) delta -= 2.0 * UI_ICON_PI;
170	    if (sweep && delta < 0.0) delta += 2.0 * UI_ICON_PI;
171	    unsigned steps = (unsigned)ceil(fabs(delta) * fmax(rx, ry) / 0.65);
172	    if (steps < 4U) steps = 4U;
173	    if (steps > 64U) steps = 64U;
174	    double px = x1, py = y1;
175	    for (unsigned step = 1U; step <= steps; ++step) {
176	        double angle = start + delta * (double)step / (double)steps;
177	        double x = cx + cosine * rx * cos(angle) - sine * ry * sin(angle);
178	        double y = cy + sine * rx * cos(angle) + cosine * ry * sin(angle);
179	        if (step == steps) { x = x2; y = y2; }
180	        if (!add_segment(segments, count, px, py, x, y)) return false;
181	        px = x; py = y;
182	    }
183	    return true;
184	}
