247	            (large != 0.0 && large != 1.0) || (sweep != 0.0 && sweep != 1.0) ||
248	            !flatten_arc(segments, out_count, x, y, rx, ry, rotation,
249	                large == 1.0, sweep == 1.0, nx, ny)) return false;
250	        x = nx; y = ny;
251	    }
252	    if (*out_count == 0U) return false;
253	    for (size_t index = 0U; index < *out_count; ++index) {
254	        if (!valid_point(segments[index].x0, segments[index].y0) ||
255	            !valid_point(segments[index].x1, segments[index].y1)) return false;
256	        bounds_include(out_bounds, segments[index].x0, segments[index].y0);
257	        bounds_include(out_bounds, segments[index].x1, segments[index].y1);
258	    }
259	    return out_bounds->left <= out_bounds->right && out_bounds->top <= out_bounds->bottom;
260	}
