310	static double distance_squared(double px, double py, const ui_icon_segment *segment)
311	{
312	    double dx = segment->x1 - segment->x0, dy = segment->y1 - segment->y0;
313	    double length_squared = dx * dx + dy * dy;
314	    double t = length_squared == 0.0 ? 0.0 :
315	        ((px - segment->x0) * dx + (py - segment->y0) * dy) / length_squared;
316	    if (t < 0.0) t = 0.0;
317	    if (t > 1.0) t = 1.0;
318	    double offset_x = px - (segment->x0 + t * dx);
319	    double offset_y = py - (segment->y0 + t * dy);
320	    return offset_x * offset_x + offset_y * offset_y;
321	}
322	
323	static bool build_icon_mask(ui_icon_kind icon, uint32_t scale,
324	                            uint8_t **out_mask, uint32_t *out_axis)
325	{
326	    if (icon <= UI_ICON_NONE || icon >= UI_ICON_COUNT || scale == 0U ||
327	        scale > UI_ICON_MAX_SCALE || out_mask == NULL || out_axis == NULL) return false;
328	    uint32_t index = (uint32_t)icon - 1U;
329	    if (!icon_mask_ready[index][scale]) {
330	        const ui_icon_definition *definitions = ui_icon_definitions(NULL);
331	        ui_icon_segment segments[UI_ICON_MAX_SEGMENTS];
332	        size_t segment_count = 0U;
333	        ui_icon_bounds parsed_bounds = {0};
334	        const ui_icon_definition *definition = &definitions[index];
335	        if (!path_parse(definition->path, definition->path_length, segments,
336	                &segment_count, &parsed_bounds)) return false;
337	        uint8_t *mask = icon_masks[index][scale];
338	        memset(mask, 0, UI_ICON_MASK_BYTES);
339	        uint32_t axis = UI_ICON_VIEWBOX * scale;
340	        const double radius_squared = 0.75 * 0.75;
341	        for (uint32_t py = 0U; py < axis; ++py) {
342	            for (uint32_t px = 0U; px < axis; ++px) {
343	                unsigned covered = 0U;
344	                for (unsigned sy = 0U; sy < UI_ICON_AA_SAMPLES; ++sy) {
345	                    for (unsigned sx = 0U; sx < UI_ICON_AA_SAMPLES; ++sx) {
346	                        double x = ((double)px + ((double)sx + 0.5) /
347	                            (double)UI_ICON_AA_SAMPLES) / (double)scale;
348	                        double y = ((double)py + ((double)sy + 0.5) /
349	                            (double)UI_ICON_AA_SAMPLES) / (double)scale;
350	                        for (size_t segment = 0U; segment < segment_count; ++segment) {
351	                            double min_x = fmin(segments[segment].x0, segments[segment].x1) - 0.8;
352	                            double max_x = fmax(segments[segment].x0, segments[segment].x1) + 0.8;
353	                            double min_y = fmin(segments[segment].y0, segments[segment].y1) - 0.8;
354	                            double max_y = fmax(segments[segment].y0, segments[segment].y1) + 0.8;
355	                            if (x < min_x || x > max_x || y < min_y || y > max_y) continue;
356	                            if (distance_squared(x, y, &segments[segment]) <= radius_squared) {
357	                                covered++;
358	                                break;
359	                            }
360	                        }
361	                    }
362	                }
363	                mask[(size_t)py * axis + px] = (uint8_t)((covered * 255U + 8U) / 16U);
364	            }
365	        }
366	        icon_mask_ready[index][scale] = true;
367	    }
368	    *out_axis = UI_ICON_VIEWBOX * scale;
369	    *out_mask = icon_masks[index][scale];
370	    return true;
371	}
372	
373	static void blend_mask_pixel(uint8_t *destination, uint32_t color, uint8_t coverage)
374	{
375	    uint32_t alpha = ((color & 255U) * coverage + 127U) / 255U;
376	    uint32_t inverse = 255U - alpha;
377	    uint32_t destination_alpha = destination[3];
378	    uint32_t out_alpha = alpha + (destination_alpha * inverse + 127U) / 255U;
379	    if (out_alpha == 0U) return;
380	    for (size_t channel = 0U; channel < 3U; ++channel) {
381	        uint32_t source = (color >> (24U - (uint32_t)(channel * 8U))) & 255U;
382	        uint32_t numerator = source * alpha * 255U +
383	            (uint32_t)destination[channel] * destination_alpha * inverse;
384	        destination[channel] = (uint8_t)((numerator + out_alpha * 127U) /
385	            (out_alpha * 255U));
386	    }
387	    destination[3] = (uint8_t)out_alpha;
388	}
