390	static bool icon_paint_cached(ui_icon_kind icon, ui_theme theme, uint32_t scale,
391	    ui_rect bounds, uint32_t color, uint8_t *rgba, uint32_t width,
392	    uint32_t height, size_t stride)
393	{
394	    if (icon == UI_ICON_NONE) return true;
395	    if (theme < UI_THEME_DARK || theme > UI_THEME_LIGHT || rgba == NULL ||
396	        width == 0U || height == 0U ||
397	        (size_t)width > SIZE_MAX / 4U || stride < (size_t)width * 4U ||
398	        (size_t)height > SIZE_MAX / stride) return false;
399	    uint8_t *mask = NULL;
400	    uint32_t icon_axis = 0U;
401	    if (!build_icon_mask(icon, scale, &mask, &icon_axis)) return false;
402	    uint64_t origin_x64 = (uint64_t)bounds.x +
403	        (bounds.width > icon_axis ? (bounds.width - icon_axis) / 2U : 0U);
404	    uint64_t origin_y64 = (uint64_t)bounds.y +
405	        (bounds.height > icon_axis ? (bounds.height - icon_axis) / 2U : 0U);
406	    if (origin_x64 > UINT32_MAX || origin_y64 > UINT32_MAX) return false;
407	    uint32_t origin_x = (uint32_t)origin_x64, origin_y = (uint32_t)origin_y64;
408	    uint32_t draw_width = bounds.width < icon_axis ? bounds.width : icon_axis;
409	    uint32_t draw_height = bounds.height < icon_axis ? bounds.height : icon_axis;
410	    if (origin_x > width || draw_width > width - origin_x ||
411	        origin_y > height || draw_height > height - origin_y) return false;
412	    for (uint32_t y = 0U; y < draw_height; ++y) {
413	        for (uint32_t x = 0U; x < draw_width; ++x) {
414	            uint8_t coverage = mask[(size_t)y * icon_axis + x];
415	            if (coverage != 0U) blend_mask_pixel(rgba +
416	                (size_t)(origin_y + y) * stride + (size_t)(origin_x + x) * 4U,
417	                color, coverage);
418	        }
419	    }
420	    return true;
421	}
