447	static uint32_t style_cache_color(ui_icon_kind icon, ui_theme theme, bool increased,
448	    uint32_t scale, ui_control_state state, uint32_t color)
449	{
450	    size_t slot = 0U;
451	    for (size_t index = 0U; index < UI_ICON_STYLE_CACHE_COUNT; ++index) {
452	        ui_icon_style_entry *entry = &icon_style_cache[index];
453	        if (entry->valid && entry->icon == icon && entry->theme == theme &&
454	            entry->increased_contrast == increased && entry->scale == scale &&
455	            entry->state == state && entry->color == color) {
456	            entry->use = ++icon_style_clock;
457	            return entry->color;
458	        }
459	        if (entry->valid && entry->icon == icon && entry->theme == theme &&
460	            entry->increased_contrast == increased && entry->scale == scale &&
461	            entry->state == state) {
462	            entry->color = color;
463	            entry->use = ++icon_style_clock;
464	            return entry->color;
465	        }
466	        if (!entry->valid) { slot = index; goto selected; }
467	        if (entry->use < icon_style_cache[slot].use) slot = index;
468	    }
469	selected:
470	    icon_style_cache[slot] = (ui_icon_style_entry){.icon = icon, .theme = theme,
471	        .increased_contrast = increased, .scale = (uint8_t)scale,
472	        .state = state, .color = color, .use = ++icon_style_clock, .valid = true};
473	    return color;
474	}
