476	bool ui_icon_paint_state_into(ui_icon_kind icon, ui_theme theme,
477	    bool increased_contrast, double backing_scale, ui_rect bounds,
478	    ui_control_state state, const ui_tokens *tokens, uint8_t *rgba,
479	    uint32_t width, uint32_t height, size_t stride)
480	{
481	    if (tokens == NULL || state < UI_CONTROL_REST || state > UI_CONTROL_INVALID ||
482	        theme < UI_THEME_DARK || theme > UI_THEME_LIGHT ||
483	        !isfinite(backing_scale) || backing_scale < 0.5 ||
484	        backing_scale > (double)UI_ICON_MAX_SCALE) return false;
485	    uint32_t scale = (uint32_t)ceil(backing_scale);
486	    uint32_t color = style_cache_color(icon, theme, increased_contrast, scale,
487	        state, state_color(tokens, state));
488	    return icon_paint_cached(icon, theme, scale, bounds, color, rgba,
489	        width, height, stride);
490	}
