492	uint64_t ui_icon_asset_hash(ui_theme theme, uint32_t integer_scale)
493	{
494	    if (theme < UI_THEME_DARK || theme > UI_THEME_LIGHT || integer_scale == 0U ||
495	        integer_scale > UI_ICON_MAX_SCALE) return 0U;
496	    uint64_t hash = UINT64_C(1469598103934665603);
497	    for (uint32_t icon = UI_ICON_SELECT; icon < UI_ICON_COUNT; ++icon) {
498	        uint8_t *mask = NULL;
499	        uint32_t axis = 0U;
500	        if (!build_icon_mask((ui_icon_kind)icon, integer_scale, &mask, &axis)) return 0U;
501	        size_t length = (size_t)axis * axis;
502	        for (size_t index = 0U; index < length; ++index) {
503	            hash ^= mask[index];
504	            hash *= UINT64_C(1099511628211);
505	        }
506	    }
507	    return hash;
508	}
