 32	static void set_pixel(uint8_t *mask, uint32_t axis, int32_t x, int32_t y,
 33	                      uint32_t stroke)
 34	{
 35	    int32_t radius = (int32_t)(stroke / 2U);
 36	    for (int32_t dy = -radius; dy <= radius; ++dy) {
 37	        for (int32_t dx = -radius; dx <= radius; ++dx) {
 38	            int32_t px = x + dx, py = y + dy;
 39	            if (px >= 0 && py >= 0 && (uint32_t)px < axis && (uint32_t)py < axis)
 40	                mask[(size_t)(uint32_t)py * axis + (uint32_t)px] = 255U;
 41	        }
 42	    }
 43	}
 44	
 45	static void draw_segment(uint8_t *mask, uint32_t axis, legacy_segment segment,
 46	                         uint32_t scale)
 47	{
 48	    int32_t x0 = (int32_t)segment.x1 * (int32_t)scale;
 49	    int32_t y0 = (int32_t)segment.y1 * (int32_t)scale;
 50	    int32_t x1 = (int32_t)segment.x2 * (int32_t)scale;
 51	    int32_t y1 = (int32_t)segment.y2 * (int32_t)scale;
 52	    int32_t dx = x1 >= x0 ? x1 - x0 : x0 - x1;
 53	    int32_t sx = x0 < x1 ? 1 : -1;
 54	    int32_t dy = y1 >= y0 ? y0 - y1 : y1 - y0;
 55	    int32_t sy = y0 < y1 ? 1 : -1;
 56	    int32_t error = dx + dy;
 57	    for (;;) {
 58	        set_pixel(mask, axis, x0, y0, (uint32_t)ceil(1.6 * (double)scale));
 59	        if (x0 == x1 && y0 == y1) break;
 60	        int32_t twice = 2 * error;
 61	        if (twice >= dy) { error += dy; x0 += sx; }
 62	        if (twice <= dx) { error += dx; y0 += sy; }
 63	    }
 64	}
