 70	        return select_geometry;
 71	    }
 72	    if (icon == UI_ICON_PAN) {
 73	        *out_count = sizeof(pan_geometry) / sizeof(pan_geometry[0]);
 74	        return pan_geometry;
 75	    }
 76	    if (icon == UI_ICON_ZOOM_IN) {
 77	        *out_count = sizeof(zoom_geometry) / sizeof(zoom_geometry[0]);
 78	        return zoom_geometry;
 79	    }
 80	    *out_count = 0U;
 81	    return NULL;
 82	}
