 84	static void blend(uint8_t *destination, uint32_t color)
 85	{
 86	    uint32_t alpha = color & 255U, inverse = 255U - alpha;
 87	    uint32_t destination_alpha = destination[3];
 88	    uint32_t out_alpha = alpha + (destination_alpha * inverse + 127U) / 255U;
 89	    if (out_alpha == 0U) return;
 90	    for (size_t channel = 0U; channel < 3U; ++channel) {
 91	        uint32_t source = (color >> (24U - (uint32_t)(channel * 8U))) & 255U;
 92	        uint32_t value = source * alpha * 255U +
 93	            (uint32_t)destination[channel] * destination_alpha * inverse;
 94	        destination[channel] = (uint8_t)((value + out_alpha * 127U) /
 95	            (out_alpha * 255U));
 96	    }
 97	    destination[3] = (uint8_t)out_alpha;
 98	}
