100	bool ui_icon_paint_legacy_into(ui_icon_kind icon, ui_theme theme,
101	    double backing_scale, ui_rect bounds, uint32_t color, uint8_t *rgba,
102	    uint32_t width, uint32_t height, size_t stride)
103	{
104	    size_t segment_count = 0U;
105	    const legacy_segment *segments = geometry(icon, &segment_count);
106	    if (icon == UI_ICON_NONE) return true;
107	    if (segments == NULL || theme > UI_THEME_LIGHT || rgba == NULL ||
108	        !isfinite(backing_scale) || backing_scale < 0.5 ||
109	        backing_scale > (double)LEGACY_MAX_SCALE || width == 0U || height == 0U ||
110	        (size_t)width > SIZE_MAX / 4U || stride < (size_t)width * 4U ||
111	        (size_t)height > SIZE_MAX / stride) return false;
112	    uint32_t scale = (uint32_t)ceil(backing_scale);
113	    uint32_t theme_index = (uint32_t)theme;
114	    uint32_t icon_index = (uint32_t)icon - 1U;
115	    uint32_t axis = 24U * scale;
116	    if (!ready[theme_index][scale][icon_index]) {
117	        uint8_t *mask = masks[theme_index][scale][icon_index];
118	        memset(mask, 0, LEGACY_MASK_BYTES);
119	        for (size_t index = 0U; index < segment_count; ++index)
120	            draw_segment(mask, axis, segments[index], scale);
121	        ready[theme_index][scale][icon_index] = true;
122	    }
123	    uint64_t origin_x64 = (uint64_t)bounds.x +
124	        (bounds.width > axis ? (bounds.width - axis) / 2U : 0U);
125	    uint64_t origin_y64 = (uint64_t)bounds.y +
126	        (bounds.height > axis ? (bounds.height - axis) / 2U : 0U);
127	    if (origin_x64 > UINT32_MAX || origin_y64 > UINT32_MAX) return false;
128	    uint32_t origin_x = (uint32_t)origin_x64, origin_y = (uint32_t)origin_y64;
129	    uint32_t draw_width = bounds.width < axis ? bounds.width : axis;
130	    uint32_t draw_height = bounds.height < axis ? bounds.height : axis;
131	    if (origin_x > width || draw_width > width - origin_x ||
132	        origin_y > height || draw_height > height - origin_y) return false;
133	    const uint8_t *mask = masks[theme_index][scale][icon_index];
134	    for (uint32_t y = 0U; y < draw_height; ++y) {
135	        for (uint32_t x = 0U; x < draw_width; ++x) {
136	            if (mask[(size_t)y * axis + x] != 0U)
137	                blend(rgba + (size_t)(origin_y + y) * stride +
138	                    (size_t)(origin_x + x) * 4U, color);
139	        }
140	    }
141	    return true;
142	}

