 23	static uint8_t ui_glyph_row(uint8_t character, size_t row)
 24	{
 25	    if (character >= 'a' && character <= 'z') character = (uint8_t)(character - 'a' + 'A');
 26	    if (character >= '0' && character <= '9') return ui_font[character - '0'][row];
 27	    if (character >= 'A' && character <= 'Z') return ui_font[10U + character - 'A'][row];
 28	    switch (character) {
 29	        case ' ': return 0U;
 30	        case '-': return row == 3U ? 14U : 0U;
 31	        case '_': return row == 6U ? 31U : 0U;
 32	        case '.': return row == 6U ? 4U : 0U;
 33	        case ',': return row == 6U ? 4U : row == 5U ? 8U : 0U;
 34	        case ':': return row == 2U || row == 5U ? 4U : 0U;
 35	        case ';': return row == 2U ? 4U : row == 5U ? 4U : row == 6U ? 8U : 0U;
 36	        case '/': return (uint8_t)(1U << (row > 4U ? 0U : 4U - row));
 37	        case '\\': return (uint8_t)(1U << (row < 5U ? row : 4U));
 38	        case '#': return row == 2U || row == 4U ? 31U : row == 1U || row == 5U ? 10U : 0U;
 39	        case '%': return row == 0U || row == 6U ? 17U : row == 1U || row == 5U ? 2U : row == 2U || row == 4U ? 4U : 8U;
 40	        case '=': return row == 2U || row == 4U ? 14U : 0U;
 41	        case '+': return row == 3U ? 14U : row == 1U || row == 2U || row == 4U || row == 5U ? 4U : 0U;
 42	        case '[': return row == 0U || row == 6U ? 14U : 8U;
 43	        case ']': return row == 0U || row == 6U ? 14U : 2U;
 44	        case '<': return row == 3U ? 2U : row == 2U || row == 4U ? 4U : row == 1U || row == 5U ? 8U : 0U;
 45	        case '>': return row == 3U ? 8U : row == 2U || row == 4U ? 4U : row == 1U || row == 5U ? 2U : 0U;
 46	        case '(': return row == 0U || row == 6U ? 2U : row == 1U || row == 5U ? 4U : 8U;
 47	        case ')': return row == 0U || row == 6U ? 8U : row == 1U || row == 5U ? 4U : 2U;
 48	        case '!': return row < 5U ? 4U : row == 6U ? 4U : 0U;
 49	        case '?': return row == 0U ? 14U : row == 1U ? 17U : row == 2U ? 2U : row == 3U ? 4U : row == 6U ? 4U : 0U;
 50	        case '\'': return row < 2U ? 4U : 0U;
 51	        case '"': return row < 2U ? 10U : 0U;
 52	        case '*': return row == 1U || row == 5U ? 10U : row == 2U || row == 4U ? 4U : row == 3U ? 14U : 0U;
 53	        case '|': return 4U;
 54	        case '&': return row == 0U ? 12U : row == 1U || row == 2U ? 18U : row == 3U ? 12U : row == 4U || row == 5U ? 21U : 10U;
 55	        default: return row == 0U || row == 6U ? 14U : row == 1U || row == 5U ? 17U : row == 2U || row == 4U ? 2U : 4U;
 56	    }
 57	}
