 59	static bool ui_pixel_valid(const ui_node *node, uint32_t x, uint32_t y,
 60	                           uint32_t width, uint32_t height)
 61	{
 62	    return x >= node->bounds.x && y >= node->bounds.y &&
 63	        x - node->bounds.x < node->bounds.width &&
 64	        y - node->bounds.y < node->bounds.height && x < width && y < height;
 65	}
