 67	static void ui_blend_pixel(uint8_t *destination, uint32_t color)
 68	{
 69	    uint32_t alpha = color & 255U;
 70	    uint32_t inverse = 255U - alpha;
 71	    uint32_t destination_alpha = destination[3];
 72	    uint32_t out_alpha = alpha + (destination_alpha * inverse + 127U) / 255U;
 73	    if (out_alpha == 0U) return;
 74	    for (size_t channel = 0U; channel < 3U; ++channel) {
 75	        uint32_t source = (color >> (24U - (uint32_t)(channel * 8U))) & 255U;
 76	        uint32_t numerator = source * alpha * 255U +
 77	            (uint32_t)destination[channel] * destination_alpha * inverse;
 78	        destination[channel] = (uint8_t)((numerator + out_alpha * 127U) / (out_alpha * 255U));
 79	    }
 80	    destination[3] = (uint8_t)out_alpha;
 81	}
