 83	static void ui_paint_rect(const ui_node *node, uint32_t color, uint8_t *rgba,
 84	                          size_t stride, uint32_t width, uint32_t height)
 85	{
 86	    uint32_t x_end = node->bounds.x + node->bounds.width;
 87	    uint32_t y_end = node->bounds.y + node->bounds.height;
 88	    if (x_end < node->bounds.x || x_end > width) x_end = width;
 89	    if (y_end < node->bounds.y || y_end > height) y_end = height;
 90	    for (uint32_t y = node->bounds.y; y < y_end; ++y)
 91	        for (uint32_t x = node->bounds.x; x < x_end; ++x)
 92	            ui_blend_pixel(rgba + (size_t)y * stride + (size_t)x * 4U, color);
 93	}
