 95	static bool ui_inside_rounded_corner(uint32_t x, uint32_t y, uint32_t width,
 96	                                     uint32_t height, uint32_t radius)
 97	{
 98	    if (radius == 0U) return true;
 99	    uint32_t dx = x < radius ? radius - x :
100	        (x >= width - radius ? x - (width - radius - 1U) : 0U);
101	    uint32_t dy = y < radius ? radius - y :
102	        (y >= height - radius ? y - (height - radius - 1U) : 0U);
103	    if (dx == 0U || dy == 0U) return true;
104	    uint64_t edge = (uint64_t)radius * radius;
105	    uint64_t distance = (uint64_t)dx * dx + (uint64_t)dy * dy;
106	    return distance <= edge;
107	}
