109	static void ui_paint_rounded_rect(const ui_node *node, uint32_t color,
110	                                  uint32_t radius, uint8_t *rgba,
111	                                  size_t stride, uint32_t width, uint32_t height)
112	{
113	    if (node->bounds.x >= width || node->bounds.y >= height) return;
114	    uint32_t right = node->bounds.x + node->bounds.width;
115	    uint32_t bottom = node->bounds.y + node->bounds.height;
116	    if (right < node->bounds.x || right > width) right = width;
117	    if (bottom < node->bounds.y || bottom > height) bottom = height;
118	    uint32_t local_width = right - node->bounds.x;
119	    uint32_t local_height = bottom - node->bounds.y;
120	    if (radius > local_width / 2U) radius = local_width / 2U;
121	    if (radius > local_height / 2U) radius = local_height / 2U;
122	    for (uint32_t y = node->bounds.y; y < bottom; ++y) {
123	        for (uint32_t x = node->bounds.x; x < right; ++x) {
124	            if (!ui_inside_rounded_corner(x - node->bounds.x, y - node->bounds.y,
125	                    local_width, local_height, radius)) continue;
126	            ui_blend_pixel(rgba + (size_t)y * stride + (size_t)x * 4U, color);
127	        }
128	    }
129	}
