131	static void ui_paint_control_outline(const ui_node *node, uint32_t color,
132	                                     uint32_t radius, uint8_t *rgba,
133	                                     size_t stride, uint32_t width,
134	                                     uint32_t height)
135	{
136	    uint32_t right = node->bounds.x + node->bounds.width;
137	    uint32_t bottom = node->bounds.y + node->bounds.height;
138	    if (right < node->bounds.x || right > width) right = width;
139	    if (bottom < node->bounds.y || bottom > height) bottom = height;
140	    uint32_t local_width = right - node->bounds.x;
141	    uint32_t local_height = bottom - node->bounds.y;
142	    if (local_width == 0U || local_height == 0U) return;
143	    if (radius > local_width / 2U) radius = local_width / 2U;
144	    if (radius > local_height / 2U) radius = local_height / 2U;
145	    for (uint32_t y = node->bounds.y; y < bottom; ++y) {
146	        for (uint32_t x = node->bounds.x; x < right; ++x) {
147	            bool edge = x == node->bounds.x || x + 1U == right ||
148	                y == node->bounds.y || y + 1U == bottom;
149	            if (!edge || !ui_inside_rounded_corner(x - node->bounds.x,
150	                    y - node->bounds.y, local_width, local_height, radius)) continue;
151	            ui_blend_pixel(rgba + (size_t)y * stride + (size_t)x * 4U, color);
152	        }
153	    }
154	}
