156	static void ui_paint_text(const char *text, size_t length, uint32_t color,
157	                          const ui_node *node, uint32_t x, uint32_t y,
158	                          uint32_t scale, uint8_t *rgba, size_t stride,
159	                          uint32_t width, uint32_t height)
160	{
161	    uint32_t right = node->bounds.x + node->bounds.width;
162	    uint32_t bottom = node->bounds.y + node->bounds.height;
163	    uint32_t cursor = x;
164	    if (length > UI_TEXT_MAX_BYTES) length = UI_TEXT_MAX_BYTES;
165	    for (size_t index = 0U; index < length; ++index) {
166	        uint8_t character = (uint8_t)text[index];
167	        if (character >= 0x80U) {
168	            if ((character & 0xc0U) == 0x80U) continue;
169	            character = '?';
170	        }
171	        if (cursor > right || right - cursor < 5U) break;
172	        for (size_t row = 0U; row < 7U; ++row) {
173	            for (size_t column = 0U; column < 5U; ++column) {
174	                if ((ui_glyph_row(character, row) & (1U << (4U - column))) == 0U) continue;
175	                for (uint32_t sy = 0U; sy < scale; ++sy) {
176	                    for (uint32_t sx = 0U; sx < scale; ++sx) {
177	                        uint32_t px = cursor + (uint32_t)column * scale + sx;
178	                        uint32_t py = y + (uint32_t)row * scale + sy;
179	                        if (px < right && py < bottom && ui_pixel_valid(node, px, py, width, height))
180	                            ui_blend_pixel(rgba + (size_t)py * stride + (size_t)px * 4U, color);
181	                    }
182	                }
183	            }
184	        }
185	        uint32_t advance = 6U * scale;
186	        if (cursor > UINT32_MAX - advance) break;
187	        cursor += advance;
188	    }
189	}
