191	static bool ui_paint_node(const ui_tree *tree, const ui_node *node, uint8_t *rgba,
192	                          size_t stride, uint32_t width, uint32_t height,
193	                          bool draw_text)
194	{
195	    uint32_t fill = node->spec.color;
196	    if ((node->spec.state & UI_STATE_PRESSED) != 0U &&
197	        (node->spec.role == UI_ROLE_BUTTON || node->spec.role == UI_ROLE_TEXT_FIELD ||
198	         node->spec.role == UI_ROLE_ROW)) fill = tree->tokens.selection_fill;
199	    else if ((node->spec.state & UI_STATE_HOVERED) != 0U &&
200	        (node->spec.role == UI_ROLE_BUTTON || node->spec.role == UI_ROLE_TEXT_FIELD ||
201	         node->spec.role == UI_ROLE_ROW)) fill = tree->tokens.panel_raised;
202	    if ((fill & 255U) != 0U) {
203	        if (tree->semantic_style && (node->spec.role == UI_ROLE_BUTTON ||
204	                node->spec.role == UI_ROLE_TEXT_FIELD))
205	            ui_paint_rounded_rect(node, fill, tree->tokens.radius, rgba, stride, width, height);
206	        else ui_paint_rect(node, fill, rgba, stride, width, height);
207	    }
208	    if (tree->semantic_style && (node->spec.role == UI_ROLE_TEXT_FIELD ||
209	            (node->spec.role == UI_ROLE_BUTTON &&
210	                node->spec.widget != UI_WIDGET_ICON_BUTTON)))
211	        ui_paint_control_outline(node, tree->tokens.control_edge,
212	            tree->tokens.radius, rgba, stride, width, height);
213	    if ((node->spec.state & UI_STATE_FOCUSED) != 0U &&
214	        node->spec.widget != UI_WIDGET_TREE_ROW &&
215	        node->bounds.width > 1U && node->bounds.height > 1U) {
216	        ui_node edge = *node;
217	        edge.bounds.height = 1U;
218	        ui_paint_rect(&edge, tree->tokens.focus_ring, rgba, stride, width, height);
219	        edge.bounds.y = node->bounds.y + node->bounds.height - 1U;
220	        ui_paint_rect(&edge, tree->tokens.focus_ring, rgba, stride, width, height);
221	        edge.bounds = (ui_rect){node->bounds.x, node->bounds.y + 1U, 1U,
222	            node->bounds.height - 2U};
223	        ui_paint_rect(&edge, tree->tokens.focus_ring, rgba, stride, width, height);
224	        edge.bounds.x = node->bounds.x + node->bounds.width - 1U;
225	        ui_paint_rect(&edge, tree->tokens.focus_ring, rgba, stride, width, height);
226	    }
227	    uint32_t color = (node->spec.state & UI_STATE_INVALID) != 0U ?
228	        tree->tokens.error : (node->spec.state & UI_STATE_DISABLED) != 0U ?
229	        tree->tokens.text_secondary : tree->tokens.text_primary;
230	    uint32_t scale = tree->tokens.font_px / 13U;
231	    if (tree->tokens.font_px % 13U != 0U) scale++;
232	    if (scale == 0U) scale = 1U;
233	    if (scale > 16U) scale = 16U;
234	    if (node->spec.role == UI_ROLE_ROW && (node->spec.state & UI_STATE_CHECKED) != 0U)
235	        color = tree->tokens.accent;
236	    if (node->spec.icon != UI_ICON_NONE) {
237	        if (!draw_text) return true;
238	        if ((node->spec.state & UI_STATE_CHECKED) != 0U) color = tree->tokens.accent;
239	        return ui_icon_paint_legacy_into(node->spec.icon, tree->theme,
240	            tree->backing_scale > 0.0 ? tree->backing_scale : 1.0,
241	            node->bounds, color, rgba, width, height, stride);
242	    }
243	    if (!draw_text) return true;
244	    uint32_t glyph_height = 7U * scale;
245	    uint32_t text_y = node->bounds.y + (node->bounds.height > glyph_height ?
246	        (node->bounds.height - glyph_height) / 2U : 0U);
247	    uint32_t inset = 8U * scale;
248	    uint32_t text_x = node->bounds.x + (node->bounds.width > inset ? inset : 0U);
249	    if (node->spec.role == UI_ROLE_BUTTON && node->spec.label_len <= 40U) {
250	        uint32_t text_width = (uint32_t)node->spec.label_len * 6U * scale;
251	        if (text_width < node->bounds.width) text_x = node->bounds.x + (node->bounds.width - text_width) / 2U;
252	    }
253	    ui_paint_text(node->label, node->spec.label_len, color, node, text_x, text_y,
254	        scale, rgba, stride, width, height);
255	    if (node->spec.role == UI_ROLE_TEXT_FIELD && node->spec.value_len > 0U) {
256	        uint32_t value_x = node->bounds.x + node->bounds.width / 2U;
257	        ui_paint_text(node->value, node->spec.value_len, color, node, value_x, text_y,
258	            scale, rgba, stride, width, height);
259	    }
260	    return true;
261	}
