263	static bool ui_tree_paint_internal(const ui_tree *tree, uint8_t *rgba,
264	                                   size_t capacity, size_t stride,
265	                                   bool draw_text)
266	{
267	    if (tree == NULL || rgba == NULL || !tree->laid_out || tree->count == 0U ||
268	        tree->count > UI_MAX_NODES) return false;
269	    uint32_t width = tree->nodes[0].bounds.width;
270	    uint32_t height = tree->nodes[0].bounds.height;
271	    if (width == 0U || height == 0U || width > RASTER_TILE_MAX_AXIS ||
272	        height > RASTER_TILE_MAX_AXIS || (size_t)width > SIZE_MAX / 4U) return false;
273	    size_t row_bytes = (size_t)width * 4U;
274	    if (stride < row_bytes || (size_t)height > SIZE_MAX / stride ||
275	        capacity < stride * (size_t)height) return false;
276	    for (size_t index = 0U; index < tree->count; ++index) {
277	        if (!tree->nodes[index].occupied) return false;
278	        if (!ui_paint_node(tree, &tree->nodes[index], rgba, stride, width, height,
279	                draw_text)) return false;
280	    }
281	    return true;
282	}
