304	        clip.width > width - clip.x || clip.height > height - clip.y) return false;
305	    uint32_t scale = font_size_px / 13U + (font_size_px % 13U != 0U ? 1U : 0U);
306	    if (scale == 0U) scale = 1U;
307	    if (scale > 16U) scale = 16U;
308	    uint32_t glyph_height = 7U * scale;
309	    uint32_t y_origin = clip.y + (clip.height > glyph_height ?
310	        (clip.height - glyph_height) / 2U : 0U);
311	    uint32_t cursor = clip.x;
312	    uint32_t right = clip.x + clip.width;
313	    uint32_t bottom = clip.y + clip.height;
314	    for (size_t index = 0U; index < length; ++index) {
315	        uint8_t character = (uint8_t)text[index];
316	        if (character >= 0x80U) {
317	            if ((character & 0xc0U) == 0x80U) continue;
318	            character = '?';
319	        }
320	        if (cursor > right || right - cursor < 5U * scale) break;
321	        for (size_t row = 0U; row < 7U; ++row) {
322	            for (size_t column = 0U; column < 5U; ++column) {
323	                if ((ui_glyph_row(character, row) & (1U << (4U - column))) == 0U) continue;
324	                for (uint32_t sy = 0U; sy < scale; ++sy) {
325	                    for (uint32_t sx = 0U; sx < scale; ++sx) {
326	                        uint32_t px = cursor + (uint32_t)column * scale + sx;
327	                        uint32_t py = y_origin + (uint32_t)row * scale + sy;
328	                        if (px >= clip.x && py >= clip.y && px < right && py < bottom &&
329	                            px < width && py < height)
330	                            ui_blend_pixel(rgba + (size_t)py * stride + (size_t)px * 4U, color);
331	                    }
332	                }
333	            }
334	        }
335	        uint32_t advance = 6U * scale;
336	        if (cursor > UINT32_MAX - advance) break;
337	        cursor += advance;
338	    }
339	    return true;
340	}

