 14	static double luminance(uint32_t color)
 15	{
 16	    return 0.2126 * linear_channel(color, 24U) +
 17	        0.7152 * linear_channel(color, 16U) +
 18	        0.0722 * linear_channel(color, 8U);
 19	}
